                <input id="avatarUrl" type="url" @bind="_displayAvatarUrl" />
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveChanges" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _displayAvatarUrl = "";

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _displayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new UserProfile(_displayName, _email, _displayAvatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;

        _saving = false;
        _showSuccess = true;

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _showSuccess = false;
    }
}

